// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";

import {
  DATATYPE_FACET_ID,
  LANGUAGE_FACET_ID,
  NODE_KIND_FACET_ID,
  NO_LANGUAGE_VALUE_ID,
  RDF_LANG_STRING,
  XSD_STRING,
  intrinsicFacetSparqlFilter,
  matchesIntrinsicFacet,
  normalizedLiteralDatatype,
  normalizedLiteralLanguage,
} from "../../../main/frontend/graph-explorer/graph-filters.ts";

const iri = { kind: "iri" };
const blank = { kind: "blank" };
const plain = { kind: "literal" };
const english = { kind: "literal", language: "EN-gb" };
const integer = {
  kind: "literal",
  datatype: "http://www.w3.org/2001/XMLSchema#integer",
};

test("node kind filtering supports OR across IRI, literal, and blank nodes", () => {
  const selected = new Set(["iri", "blank"]);
  assert.equal(
    matchesIntrinsicFacet(iri, NODE_KIND_FACET_ID, selected),
    true,
  );
  assert.equal(
    matchesIntrinsicFacet(blank, NODE_KIND_FACET_ID, selected),
    true,
  );
  assert.equal(
    matchesIntrinsicFacet(plain, NODE_KIND_FACET_ID, selected),
    false,
  );
});

test("literal datatypes use RDF 1.1 defaults when endpoint metadata is absent", () => {
  assert.equal(normalizedLiteralDatatype(plain), XSD_STRING);
  assert.equal(normalizedLiteralDatatype(english), RDF_LANG_STRING);
  assert.equal(
    normalizedLiteralDatatype(integer),
    "http://www.w3.org/2001/XMLSchema#integer",
  );
  assert.equal(normalizedLiteralDatatype(iri), null);
});

test("language filtering is case-insensitive and represents untagged literals", () => {
  assert.equal(normalizedLiteralLanguage(english), "en-gb");
  assert.equal(normalizedLiteralLanguage(plain), NO_LANGUAGE_VALUE_ID);
  assert.equal(normalizedLiteralLanguage(integer), NO_LANGUAGE_VALUE_ID);
  assert.equal(normalizedLiteralLanguage(blank), null);
});

test("metadata facets produce equivalent SPARQL focus-node filters", () => {
  assert.equal(
    intrinsicFacetSparqlFilter(
      NODE_KIND_FACET_ID,
      new Set(["iri", "blank"]),
    ),
    "FILTER(isIRI(?focus) || isBlank(?focus))",
  );
  assert.match(
    intrinsicFacetSparqlFilter(
      DATATYPE_FACET_ID,
      new Set(["http://www.w3.org/2001/XMLSchema#integer"]),
    ),
    /DATATYPE\(\?focus\)/,
  );
  assert.match(
    intrinsicFacetSparqlFilter(
      LANGUAGE_FACET_ID,
      new Set(["EN", NO_LANGUAGE_VALUE_ID]),
    ),
    /LCASE\(LANG\(\?focus\)\) = "en".*LANG\(\?focus\) = ""/,
  );
});
